558 inline D3D12_RESOURCE_DESC1 D3DX12ResourceDesc0ToDesc1(D3D12_RESOURCE_DESC const& desc0)
559 {
560     D3D12_RESOURCE_DESC1       desc1;
561     desc1.Dimension          = desc0.Dimension;
562     desc1.Alignment          = desc0.Alignment;
563     desc1.Width              = desc0.Width;
564     desc1.Height             = desc0.Height;
565     desc1.DepthOrArraySize   = desc0.DepthOrArraySize;
566     desc1.MipLevels          = desc0.MipLevels;
567     desc1.Format             = desc0.Format;
568     desc1.SampleDesc.Count   = desc0.SampleDesc.Count;
569     desc1.SampleDesc.Quality = desc0.SampleDesc.Quality;
570     desc1.Layout             = desc0.Layout;
571     desc1.Flags              = desc0.Flags;
572     desc1.SamplerFeedbackMipRegion.Width = 0;
573     desc1.SamplerFeedbackMipRegion.Height = 0;
574     desc1.SamplerFeedbackMipRegion.Depth = 0;
575     return desc1;
576 }
