579 inline bool D3DX12GetCopyableFootprints(
580     _In_  const D3D12_RESOURCE_DESC& pResourceDesc,
581     _In_range_(0, D3D12_REQ_SUBRESOURCES) UINT FirstSubresource,
582     _In_range_(0, D3D12_REQ_SUBRESOURCES - FirstSubresource) UINT NumSubresources,
583     UINT64 BaseOffset,
584     _Out_writes_opt_(NumSubresources) D3D12_PLACED_SUBRESOURCE_FOOTPRINT* pLayouts,
585     _Out_writes_opt_(NumSubresources) UINT* pNumRows,
586     _Out_writes_opt_(NumSubresources) UINT64* pRowSizeInBytes,
587     _Out_opt_ UINT64* pTotalBytes)
588 {
589     // From D3D12_RESOURCE_DESC to D3D12_RESOURCE_DESC1
590     D3D12_RESOURCE_DESC1 desc = D3DX12ResourceDesc0ToDesc1(pResourceDesc);
591     return D3DX12GetCopyableFootprints(
592         *static_cast<CD3DX12_RESOURCE_DESC1*>(&desc),// From D3D12_RESOURCE_DESC1 to CD3DX12_RESOURCE_DESC1
593         FirstSubresource,
594         NumSubresources,
595         BaseOffset,
596         pLayouts,
597         pNumRows,
598         pRowSizeInBytes,
599         pTotalBytes);
600 }
